package edu.teamfinder.config;

import edu.teamfinder.entity.*;
import edu.teamfinder.entity.Enums.*;
import edu.teamfinder.repository.*;
import java.time.LocalDate;
import java.util.*;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import edu.teamfinder.entity.Enums.Role;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@Configuration
public class DataSeeder {
    @Bean CommandLineRunner seedData(StudentRepository students,SkillRepository skills,ProjectRepository projects,TeamMemberRepository members,TeamRequestRepository requests,MilestoneRepository milestones,ActivityLogRepository activities,PasswordEncoder passwords, PlatformTransactionManager transactionManager) {
        return args -> new TransactionTemplate(transactionManager).executeWithoutResult(transaction -> { if (students.count() > 0) return;
            Map<String,Skill> catalog=new LinkedHashMap<>(); for(String name:List.of("Java","Spring Boot","MySQL","React","HTML","CSS","JavaScript","Python","Figma","Git","Docker")){Skill skill=new Skill(name);catalog.put(name,skills.save(skill));}
            Student admin=student("Priya Nair","admin@campus.dev","Information Technology",4,Availability.AVAILABLE,Role.ADMIN,"Platform administration",passwords);students.save(admin);
            Student aisha=save(students,student("Aisha Sharma","aisha@campus.dev","Computer Science",4,Availability.AVAILABLE,Role.STUDENT,"Backend, EdTech, sustainability",passwords),catalog,"Java:ADVANCED","Spring Boot:ADVANCED","MySQL:INTERMEDIATE","Git:ADVANCED","Docker:INTERMEDIATE");
            Student arjun=save(students,student("Arjun Mehta","arjun@campus.dev","Computer Science",3,Availability.AVAILABLE,Role.STUDENT,"Web development, accessibility, design systems",passwords),catalog,"React:ADVANCED","JavaScript:ADVANCED","HTML:ADVANCED","CSS:ADVANCED","Git:INTERMEDIATE");
            Student neha=save(students,student("Neha Iyer","neha@campus.dev","Information Technology",4,Availability.AVAILABLE,Role.STUDENT,"Product design, EdTech, user research",passwords),catalog,"Figma:ADVANCED","HTML:INTERMEDIATE","CSS:INTERMEDIATE","JavaScript:BEGINNER");
            Student rohan=save(students,student("Rohan Das","rohan@campus.dev","Computer Science",2,Availability.LIMITED,Role.STUDENT,"AI, data, campus life",passwords),catalog,"Python:ADVANCED","Git:INTERMEDIATE","Docker:BEGINNER");
            Student kavya=save(students,student("Kavya Rao","kavya@campus.dev","Electronics and Communication",3,Availability.AVAILABLE,Role.STUDENT,"IoT, sustainability, mobile",passwords),catalog,"Python:INTERMEDIATE","Java:INTERMEDIATE","Git:ADVANCED","Docker:BEGINNER");
            Student daniel=save(students,student("Daniel Thomas","daniel@campus.dev","Information Technology",3,Availability.AVAILABLE,Role.STUDENT,"Databases, public-interest technology",passwords),catalog,"MySQL:ADVANCED","Java:INTERMEDIATE","Spring Boot:INTERMEDIATE","Git:ADVANCED");
            Student mira=save(students,student("Mira Kapoor","mira@campus.dev","Computer Science",4,Availability.UNAVAILABLE,Role.STUDENT,"Design, student wellbeing",passwords),catalog,"Figma:ADVANCED","React:INTERMEDIATE","CSS:ADVANCED");
            Student vikram=save(students,student("Vikram Singh","vikram@campus.dev","Mechanical Engineering",4,Availability.AVAILABLE,Role.STUDENT,"Sustainability, analytics, team leadership",passwords),catalog,"Python:INTERMEDIATE","MySQL:BEGINNER","Git:INTERMEDIATE");
            Project attendance=project(projects,aisha,"Smart Attendance Companion","A privacy-aware attendance and engagement workspace for instructors.","Build a web platform that helps faculty understand attendance trends while giving students clear, respectful feedback.","EdTech",4,ProjectStatus.OPEN_FOR_MEMBERS,catalog,"Java:REQUIRED","Spring Boot:REQUIRED","MySQL:REQUIRED","React:PREFERRED","Figma:PREFERRED");lead(members,attendance,aisha);member(members,attendance,neha,TeamRole.UI_UX_DESIGNER);activity(activities,attendance,aisha,"PROJECT_CREATED","Aisha Sharma created the project."); milestone(milestones,attendance,"Research and system map","Interview stakeholders and agree core workflows.",LocalDate.now().plusDays(7),MilestoneStatus.IN_PROGRESS,55); milestone(milestones,attendance,"API foundation","Set up authentication and project APIs.",LocalDate.now().plusDays(18),MilestoneStatus.NOT_STARTED,0);
            Project eco=project(projects,kavya,"Campus Energy Lens","A shared view of energy use across campus labs and common spaces.","Prototype a data-informed dashboard that helps facilities teams identify opportunities to reduce avoidable energy use.","Sustainability",3,ProjectStatus.TEAM_FULL,catalog,"Python:REQUIRED","MySQL:REQUIRED","Docker:PREFERRED");lead(members,eco,kavya);member(members,eco,daniel,TeamRole.DATABASE_DEVELOPER);member(members,eco,vikram,TeamRole.MEMBER);activity(activities,eco,kavya,"MEMBER_JOINED","The Campus Energy Lens team is complete.");milestone(milestones,eco,"Data ingestion","Connect the first meter data source.",LocalDate.now().plusDays(5),MilestoneStatus.COMPLETED,100);
            Project portfolio=project(projects,arjun,"Peer Portfolio Review","A focused peer-feedback tool for students preparing placement portfolios.","Design and implement a workspace for structured feedback cycles with clear review prompts and version history.","Career Development",4,ProjectStatus.IN_PROGRESS,catalog,"React:REQUIRED","JavaScript:REQUIRED","Figma:PREFERRED","Spring Boot:PREFERRED");lead(members,portfolio,arjun);member(members,portfolio,neha,TeamRole.UI_UX_DESIGNER);activity(activities,portfolio,arjun,"MILESTONE_UPDATED","Prototype review milestone moved into progress.");milestone(milestones,portfolio,"Interaction prototype","Validate the feedback flow with five students.",LocalDate.now().plusDays(4),MilestoneStatus.IN_PROGRESS,70);
            Project planner=project(projects,rohan,"Study Circle Planner","A lightweight way to help students form consistent revision groups.","Explore a student-first scheduling and topic matching tool for study circles before end-semester exams.","Student Wellbeing",4,ProjectStatus.DRAFT,catalog,"Python:REQUIRED","JavaScript:PREFERRED","Figma:PREFERRED");lead(members,planner,rohan);
            Project alumni=project(projects,daniel,"Alumni Mentor Map","An accessible directory for connecting students with alumni mentors by domain.","Create an inclusive searchable directory and matching flow for a pilot alumni mentoring programme.","Community",3,ProjectStatus.COMPLETED,catalog,"Java:REQUIRED","MySQL:REQUIRED","HTML:PREFERRED","CSS:PREFERRED");lead(members,alumni,daniel);member(members,alumni,aisha,TeamRole.BACKEND_DEVELOPER);activity(activities,alumni,daniel,"PROJECT_COMPLETED","The pilot is ready for handover.");milestone(milestones,alumni,"Pilot release","Deliver the tested pilot to the alumni office.",LocalDate.now().minusDays(3),MilestoneStatus.COMPLETED,100);
            TeamRequest invite=new TeamRequest();invite.setProject(attendance);invite.setFromStudent(aisha);invite.setToStudent(arjun);invite.setStatus(RequestStatus.PENDING);requests.save(invite);
        });
    }
    private static Student student(String name,String email,String branch,int year,Availability available,Role role,String interests,PasswordEncoder encoder){Student s=new Student();s.setFullName(name);s.setEmail(email);s.setPassword(encoder.encode("CampusPass!2026"));s.setBranch(branch);s.setAcademicYear(year);s.setAvailability(available);s.setRole(role);s.setInterests(interests);s.setBio("I enjoy practical academic projects where the team communicates clearly and learns together.");return s;}
    private static Student save(StudentRepository repo,Student s,Map<String,Skill> catalog,String... pairs){for(String pair:pairs){String[] bits=pair.split(":");StudentSkill ss=new StudentSkill();ss.setStudent(s);ss.setSkill(catalog.get(bits[0]));ss.setProficiency(Proficiency.valueOf(bits[1]));s.getSkills().add(ss);}return repo.save(s);}
    private static Project project(ProjectRepository repo,Student owner,String title,String shortDesc,String desc,String category,int size,ProjectStatus status,Map<String,Skill> catalog,String... pairs){Project p=new Project();p.setOwner(owner);p.setTitle(title);p.setShortDescription(shortDesc);p.setDescription(desc);p.setCategory(category);p.setTeamSize(size);p.setStatus(status);for(String pair:pairs){String[] bits=pair.split(":");ProjectSkill ps=new ProjectSkill();ps.setProject(p);ps.setSkill(catalog.get(bits[0]));ps.setSkillType(SkillType.valueOf(bits[1]));p.getSkills().add(ps);}return repo.save(p);}
    private static void lead(TeamMemberRepository repo,Project p,Student s){member(repo,p,s,TeamRole.TEAM_LEAD);} private static void member(TeamMemberRepository repo,Project p,Student s,TeamRole role){TeamMember m=new TeamMember();m.setProject(p);m.setStudent(s);m.setRole(role);repo.save(m);}
    private static void milestone(MilestoneRepository repo,Project p,String title,String description,LocalDate due,MilestoneStatus status,int progress){Milestone m=new Milestone();m.setProject(p);m.setTitle(title);m.setDescription(description);m.setDueDate(due);m.setStatus(status);m.setProgressPercentage(progress);repo.save(m);}
    private static void activity(ActivityLogRepository repo,Project p,Student s,String type,String message){ActivityLog a=new ActivityLog();a.setProject(p);a.setStudent(s);a.setActivityType(type);a.setMessage(message);repo.save(a);}
}
